-- BATTLECRUISER M19 — Aprobaciones administrativas
-- Gastos + mermas + bajas. Aplicado y verificado en Supabase producción.

ALTER TABLE public.permisos DROP CONSTRAINT IF EXISTS permisos_seccion_check;
ALTER TABLE public.permisos ADD CONSTRAINT permisos_seccion_check CHECK (seccion = ANY (ARRAY['productos','categorias','almacenes','stock','transferencias','vales_salida','ventas','reportes','usuarios','presentaciones','auditoria','turnos','comunicacion','unidades','ciclos','entregas_caja','gastos','mermas','bajas']));

CREATE TABLE IF NOT EXISTS public.gastos (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), almacen_id uuid REFERENCES public.almacenes(id), ciclo_id uuid REFERENCES public.ciclos_operativos(id), sesion_id uuid REFERENCES public.sesiones_ciclo(id), concepto text NOT NULL, descripcion text, monto numeric(12,2) NOT NULL CHECK(monto>0), estado text NOT NULL DEFAULT 'PENDIENTE' CHECK(estado IN('PENDIENTE','APROBADO','RECHAZADO')), creado_por uuid REFERENCES public.usuarios(id), creado_nombre text, revisado_por uuid REFERENCES public.usuarios(id), revisado_nombre text, comentario_revision text, fecha_revision timestamptz, idempotency_key uuid, creado_en timestamptz NOT NULL DEFAULT now(), actualizado_en timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.mermas (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), almacen_id uuid NOT NULL REFERENCES public.almacenes(id), producto_id uuid NOT NULL REFERENCES public.productos(id), ciclo_id uuid REFERENCES public.ciclos_operativos(id), sesion_id uuid REFERENCES public.sesiones_ciclo(id), cantidad numeric(12,3) NOT NULL CHECK(cantidad>0), motivo text NOT NULL, estado text NOT NULL DEFAULT 'PENDIENTE' CHECK(estado IN('PENDIENTE','APROBADA','RECHAZADA')), creado_por uuid REFERENCES public.usuarios(id), creado_nombre text, revisado_por uuid REFERENCES public.usuarios(id), revisado_nombre text, comentario_revision text, fecha_revision timestamptz, idempotency_key uuid, creado_en timestamptz NOT NULL DEFAULT now(), actualizado_en timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.bajas (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), almacen_id uuid NOT NULL REFERENCES public.almacenes(id), producto_id uuid NOT NULL REFERENCES public.productos(id), ciclo_id uuid REFERENCES public.ciclos_operativos(id), sesion_id uuid REFERENCES public.sesiones_ciclo(id), cantidad numeric(12,3) NOT NULL CHECK(cantidad>0), motivo text NOT NULL, estado text NOT NULL DEFAULT 'PENDIENTE' CHECK(estado IN('PENDIENTE','APROBADA','RECHAZADA')), creado_por uuid REFERENCES public.usuarios(id), creado_nombre text, revisado_por uuid REFERENCES public.usuarios(id), revisado_nombre text, comentario_revision text, fecha_revision timestamptz, idempotency_key uuid, creado_en timestamptz NOT NULL DEFAULT now(), actualizado_en timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gastos_estado ON public.gastos(estado,creado_en DESC); CREATE INDEX IF NOT EXISTS idx_mermas_estado ON public.mermas(estado,creado_en DESC); CREATE INDEX IF NOT EXISTS idx_bajas_estado ON public.bajas(estado,creado_en DESC);
ALTER TABLE public.gastos ENABLE ROW LEVEL SECURITY; ALTER TABLE public.mermas ENABLE ROW LEVEL SECURITY; ALTER TABLE public.bajas ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.crear_gasto(p_concepto text,p_monto numeric,p_descripcion text DEFAULT NULL,p_almacen_id uuid DEFAULT NULL,p_ciclo_id uuid DEFAULT NULL,p_sesion_id uuid DEFAULT NULL,p_idempotency_key uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='public','pg_temp' AS $$ DECLARE v_id uuid;v_nombre text; BEGIN IF NOT public.tiene_permiso('gastos','crear') THEN RAISE EXCEPTION 'Sin permiso para registrar gastos'; END IF; IF p_concepto IS NULL OR btrim(p_concepto)='' OR p_monto IS NULL OR p_monto<=0 THEN RAISE EXCEPTION 'Concepto y monto válidos son obligatorios'; END IF; IF p_idempotency_key IS NOT NULL AND EXISTS(SELECT 1 FROM public.gastos WHERE idempotency_key=p_idempotency_key AND creado_por=auth.uid()) THEN SELECT id INTO v_id FROM public.gastos WHERE idempotency_key=p_idempotency_key AND creado_por=auth.uid() LIMIT 1; RETURN v_id; END IF; SELECT nombre INTO v_nombre FROM public.usuarios WHERE id=auth.uid(); INSERT INTO public.gastos(concepto,monto,descripcion,almacen_id,ciclo_id,sesion_id,creado_por,creado_nombre,idempotency_key) VALUES(btrim(p_concepto),p_monto,NULLIF(btrim(p_descripcion),''),p_almacen_id,p_ciclo_id,p_sesion_id,auth.uid(),v_nombre,p_idempotency_key) RETURNING id INTO v_id; RETURN v_id; END; $$;
CREATE OR REPLACE FUNCTION public.crear_merma(p_almacen_id uuid,p_producto_id uuid,p_cantidad numeric,p_motivo text,p_ciclo_id uuid DEFAULT NULL,p_sesion_id uuid DEFAULT NULL,p_idempotency_key uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='public','pg_temp' AS $$ DECLARE v_id uuid;v_nombre text; BEGIN IF NOT public.tiene_permiso('mermas','crear') THEN RAISE EXCEPTION 'Sin permiso para registrar mermas'; END IF; IF p_cantidad IS NULL OR p_cantidad<=0 OR p_motivo IS NULL OR btrim(p_motivo)='' THEN RAISE EXCEPTION 'Cantidad y motivo son obligatorios'; END IF; IF p_idempotency_key IS NOT NULL AND EXISTS(SELECT 1 FROM public.mermas WHERE idempotency_key=p_idempotency_key AND creado_por=auth.uid()) THEN SELECT id INTO v_id FROM public.mermas WHERE idempotency_key=p_idempotency_key AND creado_por=auth.uid() LIMIT 1; RETURN v_id; END IF; IF NOT EXISTS(SELECT 1 FROM public.stock WHERE almacen_id=p_almacen_id AND producto_id=p_producto_id AND cantidad>=p_cantidad) THEN RAISE EXCEPTION 'Stock insuficiente para solicitar esta merma'; END IF; SELECT nombre INTO v_nombre FROM public.usuarios WHERE id=auth.uid(); INSERT INTO public.mermas(almacen_id,producto_id,cantidad,motivo,ciclo_id,sesion_id,creado_por,creado_nombre,idempotency_key) VALUES(p_almacen_id,p_producto_id,p_cantidad,btrim(p_motivo),p_ciclo_id,p_sesion_id,auth.uid(),v_nombre,p_idempotency_key) RETURNING id INTO v_id; RETURN v_id; END; $$;
CREATE OR REPLACE FUNCTION public.crear_baja(p_almacen_id uuid,p_producto_id uuid,p_cantidad numeric,p_motivo text,p_ciclo_id uuid DEFAULT NULL,p_sesion_id uuid DEFAULT NULL,p_idempotency_key uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='public','pg_temp' AS $$ DECLARE v_id uuid;v_nombre text; BEGIN IF NOT public.tiene_permiso('bajas','crear') THEN RAISE EXCEPTION 'Sin permiso para registrar bajas'; END IF; IF p_cantidad IS NULL OR p_cantidad<=0 OR p_motivo IS NULL OR btrim(p_motivo)='' THEN RAISE EXCEPTION 'Cantidad y motivo son obligatorios'; END IF; IF p_idempotency_key IS NOT NULL AND EXISTS(SELECT 1 FROM public.bajas WHERE idempotency_key=p_idempotency_key AND creado_por=auth.uid()) THEN SELECT id INTO v_id FROM public.bajas WHERE idempotency_key=p_idempotency_key AND creado_por=auth.uid() LIMIT 1; RETURN v_id; END IF; IF NOT EXISTS(SELECT 1 FROM public.stock WHERE almacen_id=p_almacen_id AND producto_id=p_producto_id AND cantidad>=p_cantidad) THEN RAISE EXCEPTION 'Stock insuficiente para solicitar esta baja'; END IF; SELECT nombre INTO v_nombre FROM public.usuarios WHERE id=auth.uid(); INSERT INTO public.bajas(almacen_id,producto_id,cantidad,motivo,ciclo_id,sesion_id,creado_por,creado_nombre,idempotency_key) VALUES(p_almacen_id,p_producto_id,p_cantidad,btrim(p_motivo),p_ciclo_id,p_sesion_id,auth.uid(),v_nombre,p_idempotency_key) RETURNING id INTO v_id; RETURN v_id; END; $$;
CREATE OR REPLACE FUNCTION public.listar_aprobaciones_admin() RETURNS TABLE(tipo text,id uuid,fecha timestamptz,usuario_nombre text,almacen_nombre text,producto_nombre text,resumen text,monto numeric,cantidad numeric,estado text,motivo text) LANGUAGE sql SECURITY DEFINER SET search_path='public','pg_temp' AS $$ SELECT 'gasto',g.id,g.creado_en,g.creado_nombre,a.nombre,NULL,g.concepto,g.monto,NULL,g.estado,g.descripcion FROM public.gastos g LEFT JOIN public.almacenes a ON a.id=g.almacen_id WHERE g.estado='PENDIENTE' UNION ALL SELECT 'merma',m.id,m.creado_en,m.creado_nombre,a.nombre,p.nombre,'Merma de inventario',NULL,m.cantidad,m.estado,m.motivo FROM public.mermas m JOIN public.almacenes a ON a.id=m.almacen_id JOIN public.productos p ON p.id=m.producto_id WHERE m.estado='PENDIENTE' UNION ALL SELECT 'baja',b.id,b.creado_en,b.creado_nombre,a.nombre,p.nombre,'Baja de inventario',NULL,b.cantidad,b.estado,b.motivo FROM public.bajas b JOIN public.almacenes a ON a.id=b.almacen_id JOIN public.productos p ON p.id=b.producto_id WHERE b.estado='PENDIENTE' ORDER BY 3 DESC; $$;
CREATE OR REPLACE FUNCTION public._aplicar_salida_aprobada(p_almacen_id uuid,p_producto_id uuid,p_cantidad numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='public','pg_temp' AS $$ DECLARE v_stock numeric;v_restante numeric;v_l record;v_tomar numeric; BEGIN SELECT cantidad INTO v_stock FROM public.stock WHERE almacen_id=p_almacen_id AND producto_id=p_producto_id FOR UPDATE; IF v_stock IS NULL OR v_stock<p_cantidad THEN RAISE EXCEPTION 'Stock insuficiente al aprobar la salida'; END IF; v_restante:=p_cantidad; FOR v_l IN SELECT id,cantidad_restante FROM public.lotes_compra WHERE almacen_id=p_almacen_id AND producto_id=p_producto_id AND cantidad_restante>0 ORDER BY fecha_compra ASC FOR UPDATE LOOP EXIT WHEN v_restante<=0; v_tomar:=LEAST(v_l.cantidad_restante,v_restante); UPDATE public.lotes_compra SET cantidad_restante=cantidad_restante-v_tomar WHERE id=v_l.id; v_restante:=v_restante-v_tomar; END LOOP; IF v_restante>0 THEN RAISE EXCEPTION 'No existe trazabilidad FIFO suficiente para aprobar la salida'; END IF; UPDATE public.stock SET cantidad=cantidad-p_cantidad,updated_at=now() WHERE almacen_id=p_almacen_id AND producto_id=p_producto_id; END; $$;
CREATE OR REPLACE FUNCTION public.resolver_aprobacion_operativa(p_tipo text,p_id uuid,p_decision text,p_comentario text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='public','pg_temp' AS $$ DECLARE v_nombre text;v_alm uuid;v_prod uuid;v_cant numeric;v_estado text; BEGIN IF NOT(public.tiene_permiso('auditoria','editar_any') OR public.tiene_permiso('gastos','editar_any') OR public.tiene_permiso('mermas','editar_any') OR public.tiene_permiso('bajas','editar_any')) THEN RAISE EXCEPTION 'Sin permiso administrativo para aprobar operaciones'; END IF; IF p_decision NOT IN('APROBAR','RECHAZAR') THEN RAISE EXCEPTION 'Decisión inválida'; END IF; IF p_decision='RECHAZAR' AND(p_comentario IS NULL OR btrim(p_comentario)='') THEN RAISE EXCEPTION 'El rechazo requiere un motivo'; END IF; SELECT nombre INTO v_nombre FROM public.usuarios WHERE id=auth.uid(); IF p_tipo='gasto' THEN SELECT estado INTO v_estado FROM public.gastos WHERE id=p_id FOR UPDATE; IF v_estado IS NULL OR v_estado<>'PENDIENTE' THEN RAISE EXCEPTION 'Gasto no pendiente o inexistente'; END IF; UPDATE public.gastos SET estado=CASE WHEN p_decision='APROBAR' THEN 'APROBADO' ELSE 'RECHAZADO' END,revisado_por=auth.uid(),revisado_nombre=v_nombre,comentario_revision=NULLIF(btrim(p_comentario),''),fecha_revision=now(),actualizado_en=now() WHERE id=p_id; ELSIF p_tipo='merma' THEN SELECT estado,almacen_id,producto_id,cantidad INTO v_estado,v_alm,v_prod,v_cant FROM public.mermas WHERE id=p_id FOR UPDATE; IF v_estado IS NULL OR v_estado<>'PENDIENTE' THEN RAISE EXCEPTION 'Merma no pendiente o inexistente'; END IF; IF p_decision='APROBAR' THEN PERFORM public._aplicar_salida_aprobada(v_alm,v_prod,v_cant); END IF; UPDATE public.mermas SET estado=CASE WHEN p_decision='APROBAR' THEN 'APROBADA' ELSE 'RECHAZADA' END,revisado_por=auth.uid(),revisado_nombre=v_nombre,comentario_revision=NULLIF(btrim(p_comentario),''),fecha_revision=now(),actualizado_en=now() WHERE id=p_id; ELSIF p_tipo='baja' THEN SELECT estado,almacen_id,producto_id,cantidad INTO v_estado,v_alm,v_prod,v_cant FROM public.bajas WHERE id=p_id FOR UPDATE; IF v_estado IS NULL OR v_estado<>'PENDIENTE' THEN RAISE EXCEPTION 'Baja no pendiente o inexistente'; END IF; IF p_decision='APROBAR' THEN PERFORM public._aplicar_salida_aprobada(v_alm,v_prod,v_cant); END IF; UPDATE public.bajas SET estado=CASE WHEN p_decision='APROBAR' THEN 'APROBADA' ELSE 'RECHAZADA' END,revisado_por=auth.uid(),revisado_nombre=v_nombre,comentario_revision=NULLIF(btrim(p_comentario),''),fecha_revision=now(),actualizado_en=now() WHERE id=p_id; ELSE RAISE EXCEPTION 'Tipo de aprobación desconocido'; END IF; RETURN jsonb_build_object('ok',true,'tipo',p_tipo,'id',p_id,'decision',p_decision,'revisado_por',v_nombre); END; $$;
REVOKE ALL ON FUNCTION public.crear_gasto(text,numeric,text,uuid,uuid,uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.crear_gasto(text,numeric,text,uuid,uuid,uuid,uuid) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.crear_merma(uuid,uuid,numeric,text,uuid,uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.crear_merma(uuid,uuid,numeric,text,uuid,uuid,uuid) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.crear_baja(uuid,uuid,numeric,text,uuid,uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.crear_baja(uuid,uuid,numeric,text,uuid,uuid,uuid) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.listar_aprobaciones_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.listar_aprobaciones_admin() TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.resolver_aprobacion_operativa(text,uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.resolver_aprobacion_operativa(text,uuid,text,text) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public._aplicar_salida_aprobada(uuid,uuid,numeric) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public._aplicar_salida_aprobada(uuid,uuid,numeric) TO authenticated,service_role;
INSERT INTO public.permisos(role_id,seccion,accion,permitido) SELECT r.id,s.seccion,s.accion,true FROM public.roles r CROSS JOIN (VALUES('gastos','ver'),('gastos','crear'),('gastos','editar_any'),('mermas','ver'),('mermas','crear'),('mermas','editar_any'),('bajas','ver'),('bajas','crear'),('bajas','editar_any')) s(seccion,accion) WHERE lower(r.nombre) IN('dueño','admin','administrador') ON CONFLICT(role_id,seccion,accion) DO UPDATE SET permitido=EXCLUDED.permitido;
